from requests import Request
from requests.models import Request
from collections.abc import Iterable

class ProxyIterable:
    def __init__(self, data):
        self._data = data

    def __getattr__(self, name):
        return getattr(self._data, name)

def test_proxy_iterable():
    data = ProxyIterable(iter([1, 2, 3]))
    # In the current implementation, isinstance(data, Iterable) will be False
    # because ProxyIterable does not inherit from Iterable and doesn't implement __iter__ directly.
    # However, it has __iter__ via __getattr__.

    req = Request('POST', 'http://http.bin.org', data=data)
    prep = req.prepare()

    # If it's detected as a stream, Transfer-Encoding should be 'chunked' 
    # (unless it has a length, but iter([1,2,3]) doesn't have a length)
    print(f"Headers: {prep.headers}")
    assert prep.headers.get('Transfer-Encoding') == 'chunked'

if __name__ == "__main__":
    try:
        test_proxy_iterable()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()
